package com.modelrag.server.health;
import org.springframework.context.annotation.Profile; import org.springframework.boot.health.contributor.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Component;
@Component("pgvector") @Profile("!test") public class PgVectorHealthIndicator implements HealthIndicator {private final JdbcTemplate jdbc;public PgVectorHealthIndicator(JdbcTemplate jdbc){this.jdbc=jdbc;}public Health health(){try{Integer count=jdbc.queryForObject("SELECT count(*) FROM pg_extension WHERE extname='vector'",Integer.class);return count!=null&&count>0?Health.up().withDetail("extension","vector").build():Health.down().withDetail("reason","vector extension missing").build();}catch(Exception e){return Health.down(e).build();}}}
